import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

/**
 * Secure implementation of an Atom provider.
 *
 * <p>The original implementation reused a shared {@link Parser} instance and
 * configured its {@link ParserOptions} inside a synchronized block.  This
 * approach did not guarantee that the security‑related options (e.g.
 * {@code setResolveEntities(false)}) were applied before parsing, especially
 * when the parser was accessed concurrently by multiple threads.  An attacker
 * could therefore trigger XML External Entity (XXE) processing.</p>
 *
 * <p>The patched version creates a fresh {@link ParserOptions} object for each
 * request, configures it to disable entity resolution, and passes it explicitly
 * to {@link Parser#parse(InputStream, ParserOptions)}.  No shared mutable state
 * is used, eliminating race conditions and ensuring the parser is always
 * operating in a hardened configuration.</p>
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // other methods ...

    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // Obtain a fresh parser from the Abdera engine.  The parser itself is
        // stateless; the security configuration is applied via a dedicated
        // ParserOptions instance that is not shared.
        Parser parser = ATOM_ENGINE.getParser();

        // Build parser options that explicitly disable all forms of entity
        // expansion.  This prevents XXE attacks.
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        // Disallow resolution of external entities (the critical mitigation).
        options.setResolveEntities(false);
        // Some Abdera versions also support an explicit flag for entity
        // expansion; setting it to false adds an extra layer of safety.
        try {
            options.getClass()
                   .getMethod("setExpandEntities", boolean.class)
                   .invoke(options, false);
        } catch (ReflectiveOperationException ignored) {
            // Method not present in this version – the previous call to
            // setResolveEntities(false) is sufficient.
        }

        // Parse the input using the hardened options.  The parse method that
        // accepts ParserOptions guarantees that the configuration is applied
        // before any XML processing begins.
        Document<T> doc = parser.parse(entityStream, options);

        // Return the root element of the parsed document.
        return doc.getRoot();
    }

    // other methods ...

}
