    /**
     * Returns the regular expression used for client‑side URL validation.
     *
     * <p>The method now safely handles {@code null} or blank values for
     * {@code urlRegexExpression} and {@code urlRegex}.  If a custom expression
     * is supplied it is parsed; any parsing error results in falling back to the
     * predefined safe default.</p>
     *
     * @return a non‑null regular expression string.
     */
    public String getUrlRegex() {
        // 1. Prefer a user‑supplied expression (urlRegexExpression)
        if (StringUtils.isNotBlank(urlRegexExpression)) {
            try {
                // parse may throw; we guard against it.
                Object parsed = parse(urlRegexExpression, String.class);
                if (parsed instanceof String && StringUtils.isNotBlank((String) parsed)) {
