                }
                // If parsing yields a non‑string or blank, fall through to safe default.
                LOG.log(Level.WARNING,
                        "Parsed urlRegexExpression is not a non‑blank String; using default regex.");
            } catch (Exception e) {
                LOG.log(Level.WARNING,
                        "Failed to parse urlRegexExpression; using default regex.", e);
            }
        }

        // 2. Fallback to the explicitly set urlRegex field
        if (StringUtils.isNotBlank(urlRegex)) {
            return urlRegex;
        }

        // 3. Final safe default – never returns null.
        return DEFAULT_URL_REGEX;
