static public File allocateFile(File dir, String name) {
    if (dir == null) {
        throw new IllegalArgumentException("Target directory must not be null");
    }
    // Ensure dir exists and is a directory
    if (!dir.isDirectory()) {
        if (!dir.mkdirs()) {
            throw new IllegalArgumentException("Unable to create target directory: " + dir);
        }
    }

    if (name == null) {
        throw new IllegalArgumentException("File name must not be null");
    }

    // Strip query part
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }

    // Normalize name: remove any path separators to prevent sub‑directories
    if (name.contains("/") || name.contains("\\") || name.contains(File.separator)) {
        // replace with underscore or reject
        name = name.replace("/", "_").replace("\\", "_");
    }

    // Trim whitespace
    name = name.trim();
    if (name.isEmpty()) {
        throw new IllegalArgumentException("File name must not be empty");
    }

    // Build initial file and verify it stays inside dir
    File file = new File(dir, name);
    try {
        File canonicalDir = dir.getCanonicalFile();
        File canonicalFile = file.getCanonicalFile();
        if (!canonicalFile.getPath().startsWith(canonicalDir.getPath() + File.separator)) {
            throw new IllegalArgumentException("Invalid file name, path traversal detected: " + name);
        }
        file = canonicalFile;
    } catch (IOException e) {
        throw new IllegalArgumentException("Failed to resolve file path", e);
    }

    // Determine prefix/suffix for duplicate handling
    int dot = name.lastIndexOf('.');
    String prefix = dot < 0 ? name : name.substring(0, dot);
    String suffix = dot < 0 ? "" : name.substring(dot);
    int index = 2;
    while (file.exists()) {
        String newName = prefix + "-" + index++ + suffix;
        file = new File(dir, newName);
        try {
            File canonicalFile = file.getCanonicalFile();
            if (!canonicalFile.getPath().startsWith(dir.getCanonicalPath() + File.separator)) {
                throw new IllegalArgumentException("Invalid generated file name, path traversal detected");
            }
            file = canonicalFile;
        } catch (IOException e) {
            throw new IllegalArgumentException("Failed to resolve generated file path", e);
        }
    }

    // Ensure parent directories exist
    File parent = file.getParentFile();
    if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
        throw new IllegalArgumentException("Unable to create directories for file: " + parent);
    }

    return file;
}
