protected void extractFile(final File srcF,
                          final File dir,
                          final InputStream compressedInputStream,
                          final String entryName,
                          final Date entryDate,
                          final boolean isDirectory,
                          final Integer mode,
                          String symlinkDestination) throws IOException, ArchiverException {

    if (entryName == null) {
        throw new ArchiverException("Entry name is null");
    }

    // Resolve the target file inside the destination directory
    final File target = FileUtils.resolveFile(dir, entryName);

    // -----------------------------------------------------------------
    // Zip‑Slip protection: ensure that the resolved file stays inside `dir`
    // -----------------------------------------------------------------
    final Path canonicalDirPath = dir.getCanonicalFile().toPath();
    final Path canonicalTargetPath = target.getCanonicalFile().toPath();

    if (!canonicalTargetPath.startsWith(canonicalDirPath)) {
        throw new ArchiverException(
                "Entry is outside of the target directory (" + entryName + ")");
    }

    // Prevent overwriting an existing symbolic link with a regular file
    if (StringUtils.isEmpty(symlinkDestination) && Files.isSymbolicLink(canonicalTargetPath)) {
        throw new ArchiverException(
                "Refusing to overwrite existing symbolic link with regular file (" + entryName + ")");
    }

    try {
        // Respect the overwrite flag and modification time
        if (!isOverwrite() && target.exists()
                && target.lastModified() >= entryDate.getTime()) {
            return;
        }

        // Ensure parent directories exist
        final File parent = target.getParentFile();
        if (parent != null) {
            parent.mkdirs();
        }

        if (!StringUtils.isEmpty(symlinkDestination)) {
            // Create a symbolic link
            SymlinkUtils.createSymbolicLink(target, new File(symlinkDestination));
        } else if (isDirectory) {
            // Create a directory entry
            target.mkdirs();
        } else {
            // Extract regular file
            try (OutputStream out = new FileOutputStream(target)) {
                IOUtil.copy(compressedInputStream, out);
            }
        }

        // Preserve timestamps
        target.setLastModified(entryDate.getTime());

        // Preserve Unix permissions when required
        if (!isIgnorePermissions() && mode != null && !isDirectory) {
            ArchiveEntryUtils.chmod(target, mode);
        }
    } catch (final FileNotFoundException ex) {
        getLogger().warn("Unable to expand to file " + target.getPath());
    }
}
