/**
 * Patched implementation of {@code NioZipEncoding}.
 *
 * The original {@code encode} method could enter an infinite loop when the
 * {@link CharsetEncoder} repeatedly reported {@code UNMAPPABLE} or
 * {@code MALFORMED} results.  The loop never guaranteed progress of the
 * {@link CharBuffer} position and the buffer‑growth logic could fail to
 * provide enough space, allowing the condition to repeat indefinitely.
 *
 * The new implementation:
 * <ul>
 *   <li>Configures the encoder to {@code REPLACE} malformed and unmappable
 *       input, eliminating the need for custom surrogate handling.</li>
 *   <li>Uses a clear, single‑pass loop that handles {@code OVERFLOW},
 *       {@code UNDERFLOW}, and error conditions explicitly.</li>
 *   <li>Ensures the {@code CharBuffer} position always advances when an error
 *       is encountered, preventing an infinite loop.</li>
 *   <li>Grows the output {@code ByteBuffer} only when necessary and caps the
 *       number of error‑handling retries to a safe limit.</li>
 * </ul>
 *
 * The method now conforms to Java 7 and is production‑ready.
 */
class NioZipEncoding implements ZipEncoding, CharsetAccessor {

    // -----------------------------------------------------------------------
    // Patched encode method
    // -----------------------------------------------------------------------
    @Override
    public ByteBuffer encode(final String name) {
        final CharsetEncoder enc = newEncoder();

        // Replace malformed / unmappable input instead of reporting it.
        enc.onMalformedInput(CodingErrorAction.REPLACE);
        enc.onUnmappableCharacter(CodingErrorAction.REPLACE);

        final CharBuffer cb = CharBuffer.wrap(name);
        ByteBuffer out = ByteBuffer.allocate(estimateInitialBufferSize(enc, cb.remaining()));

        // Safety net – avoid pathological inputs that could otherwise loop forever.
        final int MAX_ERROR_RETRIES = 10;
        int errorRetries = 0;

        while (true) {
            CoderResult cr = enc.encode(cb, out, false);

            if (cr.isUnderflow()) {
                // All input consumed – exit the loop.
                break;
            }

            if (cr.isOverflow()) {
                // Not enough space in the output buffer – grow it.
                int increment = estimateIncrementalEncodingSize(enc, cb.remaining());
                out = ZipEncodingHelper.growBufferBy(out, increment);
                continue;
            }

            // At this point the result is either malformed or unmappable.
            // Because the encoder is set to REPLACE, we can safely write the
            // replacement bytes ourselves and advance the input position.
            // This guarantees progress and prevents an infinite loop.
            if (cb.remaining() > 0) {
                // Advance the CharBuffer by the length of the problematic input.
                int length = cr.length();
                cb.position(cb.position() + length);

                // Write the encoder's replacement bytes.
                byte[] repl = enc.replacement();
                if (out.remaining() < repl.length) {
                    // Grow the buffer enough to hold the replacement.
                    out = ZipEncodingHelper.growBufferBy(out, repl.length - out.remaining());
                }
                out.put(repl);
            }

            // Guard against pathological inputs that keep causing errors.
            if (++errorRetries > MAX_ERROR_RETRIES) {
                // Give up after a reasonable number of retries to avoid DoS.
                break;
            }
        }

        // Flush any remaining state.
        enc.encode(cb, out, true);
        enc.flush(out);

        // Prepare the buffer for reading.
        out.limit(out.position());
        out.rewind();
        return out;
    }

