private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
    // Resolve the target directory to its real (canonical) path once.
    final Path targetPath = targetDirectory.toPath().toRealPath().normalize();

    ArchiveEntry entry = supplier.getNextReadableEntry();
    while (entry != null) {
        String entryName = entry.getName();

        // Reject null or empty names.
        if (entryName == null || entryName.trim().isEmpty()) {
            throw new IOException("Archive entry has an empty name");
        }

        // Normalise separators to '/' to make processing platform independent.
        entryName = entryName.replace('\\', '/');

        // Remove any leading '/' to avoid absolute paths.
        while (entryName.startsWith("/")) {
            entryName = entryName.substring(1);
        }

        // Resolve the entry against the target directory and normalise.
        Path resolvedPath = targetPath.resolve(entryName).normalize();

        // Ensure the resolved path is still inside the target directory.
        if (!resolvedPath.startsWith(targetPath)) {
            throw new IOException("expanding " + entry.getName()
                    + " would create file outside of " + targetDirectory);
        }

        if (entry.isDirectory() || entryName.endsWith("/")) {
            // Create the directory (including any missing parents).
            Files.createDirectories(resolvedPath);
        } else {
            // Ensure parent directory exists.
            Path parent = resolvedPath.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }

            // Write the file content.
            try (OutputStream out = Files.newOutputStream(resolvedPath)) {
                writer.writeEntryDataTo(entry, out);
            }

            // After writing, double‑check that the file still resides inside the target directory.
            // This protects against symlink attacks where the parent directory could be a symlink.
            if (!resolvedPath.toRealPath().startsWith(targetPath)) {
                // Attempt to delete the potentially malicious file before aborting.
                try {
                    Files.deleteIfExists(resolvedPath);
                } catch (IOException ignored) {
                }
                throw new IOException("expanding " + entry.getName()
                        + " resulted in a file outside of " + targetDirectory);
            }
        }

        entry = supplier.getNextReadableEntry();
    }
}
