     */
    public Calendar ceil(Calendar cal) {
        // Clone the input calendar to represent a date two years in the future.
        Calendar twoYearsFuture = (Calendar) cal.clone();
        twoYearsFuture.add(Calendar.YEAR, 2);

        // -----------------------------------------------------------------
        // Defensive loop control – prevent an infinite loop (DoS vector).
        // -----------------------------------------------------------------
        //   * MAX_ITERATIONS is a hard‑coded safety net. The value is chosen
        //     to be comfortably larger than any realistic number of
        //     adjustments required for a valid cron expression while still
        //     guaranteeing termination.
        //   * After each outer iteration we verify that the calendar has
        //     actually moved forward; if not, we abort with a clear
        //     exception. This catches pathological field implementations
        //     that could otherwise keep the loop alive forever.
        // -----------------------------------------------------------------
        final int MAX_ITERATIONS = 1_000;          // generous safety bound
        int iterationCount = 0;

        OUTER: while (true) {
            // -----------------------------------------------------------------
            // 1. Guard against runaway iterations.
            // -----------------------------------------------------------------
            if (iterationCount++ > MAX_ITERATIONS) {
                throw new RareOrImpossibleDateException(
                        "Ceiling calculation exceeded safe iteration limit (" + MAX_ITERATIONS + ").");
            }

            // Remember the current instant to detect lack of progress later.
            long beforeMillis = cal.getTimeInMillis();

            // -----------------------------------------------------------------
            // 2. Abort if we have stepped beyond the two‑year horizon.
            // -----------------------------------------------------------------
            if (cal.compareTo(twoYearsFuture) > 0) {
                throw new RareOrImpossibleDateException(
                        "Date is too rare or impossible within the next two years.");
            }

            // -----------------------------------------------------------------
            // 3. Walk through the fields in the defined adjustment order.
            // -----------------------------------------------------------------
            for (CalendarField f : CalendarField.ADJUST_ORDER) {

                int cur = f.valueOf(cal);
                int next = f.ceil(this, cur);

                // No change required for this field – continue with the next one.
                if (cur == next) {
                    continue;
                }

                // Reset all lower‑significance fields because a higher field changed.
                for (CalendarField l = f.lowerField; l != null; l = l.lowerField) {
                    l.clear(cal);
                }

                // -----------------------------------------------------------------
                // 4. Handle the case where the next valid value is “negative”.
                //    This means the current field has overflowed and must roll up.
                // -----------------------------------------------------------------
                if (next < 0) {
                    f.rollUp(cal, 1);
                    f.setTo(cal, f.first(this));
                    // Restart the whole adjustment process because higher fields changed.
                    continue OUTER;
                } else {
                    // Normal case – set the field to the computed next value.
                    f.setTo(cal, next);

                    // Some fields (e.g., day‑of‑month) may require a full re‑evaluation
                    // after being modified because they affect other fields.
                    if (f.redoAdjustmentIfModified) {
                        continue OUTER;
                    }
                }
            }

            // -----------------------------------------------------------------
            // 5. Verify that the loop made forward progress.
            // -----------------------------------------------------------------
            if (cal.getTimeInMillis() == beforeMillis) {
                // No progress – this would otherwise cause an infinite loop.
                throw new RareOrImpossibleDateException(
                        "Ceiling calculation made no progress; possible malformed cron expression.");
            }

            // All fields are now valid – return the adjusted calendar.
            return cal;
        }
    }

