protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
    if (body == null) {
        return null;
    }
    Object answer = null;
    Class<?> type = getDocumentType();
    Exception cause = null;

    // If a specific document type is requested, try to honour it securely
    if (type != null) {
        try {
            // First try the generic type conversion provided by Camel
            answer = exchange.getContext().getTypeConverter().convertTo(type, exchange, body);
        } catch (Exception e) {
            cause = e;
        }

        // If the caller expects a DOM Document (or a subclass) we can safely
        // parse the XML ourselves with a hardened parser. This avoids returning
        // an InputSource that could be processed by an insecure parser later.
        if (answer == null && Document.class.isAssignableFrom(type)) {
            try {
                InputSource source = null;
                if (body instanceof WrappedFile) {
                    InputStream is = exchange.getContext().getTypeConverter()
                            .convertTo(InputStream.class, exchange, body);
                    if (is != null) {
                        source = new InputSource(is);
                    }
                } else if (body instanceof String) {
                    source = new InputSource(new StringReader((String) body));
                } else if (body instanceof InputStream) {
                    source = new InputSource((InputStream) body);
                }

                if (source != null) {
                    answer = parseSecureDocument(source);
                }
            } catch (Exception e) {
                // Preserve the original conversion exception if parsing also fails
                if (cause == null) {
                    cause = e;
                }
            }
        }
    }

    // Fallback handling when no explicit document type is configured
    if (answer == null) {
        if (body instanceof WrappedFile) {
            InputStream is = exchange.getContext().getTypeConverter()
                    .convertTo(InputStream.class, exchange, body);
            if (is != null) {
                // Return a secure InputSource only when the caller explicitly
                // asked for it (i.e., document type is null). The InputSource
                // itself does not trigger parsing, so the risk is deferred
                // to the downstream parser. To minimise risk we still set a
                // dummy EntityResolver later is not possible here, therefore
                // we prefer to return a parsed Document when possible.
                answer = new InputSource(is);
            }
        } else if (body instanceof BeanInvocation) {
            BeanInvocation bi = exchange.getContext().getTypeConverter()
                    .convertTo(BeanInvocation.class, exchange, body);
            if (bi.getArgs() != null && bi.getArgs().length == 1 && bi.getArgs()[0] == null) {
                answer = null;
            }
        } else if (body instanceof String) {
            // As a last resort we return the raw string. The caller should
            // treat it as data, not as a parsed XML document.
            answer = new InputSource(new StringReader((String) body));
        }
    }

    if (type == null && answer == null) {
        answer = body;
    } else if (answer == null) {
        if (cause != null) {
            throw cause;
        } else {
            throw new NoTypeConversionAvailableException(body, type);
        }
    }
    return answer;
}

/**
 * Parses the supplied {@link InputSource} into a DOM {@link Document} using a
 * {@link DocumentBuilderFactory} that has been hardened against XML External
 * Entity (XXE) attacks.
 *
 * @param source the XML source to parse
 * @return a safe {@link Document}
 * @throws Exception if parsing fails
 */
private Document parseSecureDocument(InputSource source) throws Exception {
    // Create a new factory for each call to avoid accidental reuse of a
    // globally‑configured (and potentially insecure) factory.
    DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

    // The following features are recommended by OWASP to prevent XXE.
    dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
    dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
    dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
    dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
    dbf.setXIncludeAware(false);
    dbf.setExpandEntityReferences(false);
    dbf.setNamespaceAware(true);

    DocumentBuilder builder = dbf.newDocumentBuilder();
    // Prevent the builder from resolving external entities via a custom resolver.
    builder.setEntityResolver((publicId, systemId) -> new InputSource(new StringReader("")));
