     * @param exchange the current Camel {@link Exchange} (may be {@code null})
     * @return a securely configured {@link SAXSource}
     * @throws SAXException if a parsing component cannot be instantiated
     */
    @Converter
    public SAXSource toSAXSourceFromStream(StreamSource source, Exchange exchange) throws SAXException {
        if (source == null) {
            throw new IllegalArgumentException("StreamSource must not be null");
        }

        // -----------------------------------------------------------------
        // Build the InputSource from the StreamSource (reader takes precedence)
        // -----------------------------------------------------------------
        InputSource inputSource;
        try {
            if (source.getReader() != null) {
                inputSource = new InputSource(source.getReader());
            } else if (source.getInputStream() != null) {
                inputSource = new InputSource(source.getInputStream());
            } else {
                // Neither a Reader nor an InputStream – nothing to parse.
                throw new IllegalArgumentException("StreamSource does not contain a Reader or InputStream");
            }
        } catch (Exception e) {
            // Wrap any I/O related exception as a SAXException to keep the method signature.
            throw new SAXException("Failed to create InputSource from StreamSource", e);
        }

        inputSource.setSystemId(source.getSystemId());
        inputSource.setPublicId(source.getPublicId());

        // -----------------------------------------------------------------
        // Obtain and harden the SAXParserFactory
        // -----------------------------------------------------------------
        SAXParserFactory sfactory = null;
        if (exchange != null) {
            sfactory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
        }
        if (sfactory == null) {
            sfactory = SAXParserFactory.newInstance();
        }

        // The factory must be namespace‑aware for most XML processing.
        sfactory.setNamespaceAware(true);

        // Apply security‑related features. Each call is isolated so that a failure
        // on one feature does not prevent the others from being set.
        try {
            sfactory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        } catch (Exception e) {
            LOG.warn("SAXParserFactory does not support FEATURE_SECURE_PROCESSING: {}", e.getMessage());
        }
        try {
            sfactory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        } catch (Exception e) {
            LOG.warn("Failed to disable external-general-entities: {}", e.getMessage());
        }
        try {
            sfactory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        } catch (Exception e) {
            LOG.warn("Failed to disable external-parameter-entities: {}", e.getMessage());
        }
        try {
            sfactory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        } catch (Exception e) {
            LOG.warn("Failed to disable loading of external DTDs: {}", e.getMessage());
        }
        try {
            sfactory.setFeature("http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);
        } catch (Exception e) {
            LOG.warn("Failed to disable loading of DTD grammar: {}", e.getMessage());
        }

        // -----------------------------------------------------------------
        // Create the XMLReader and apply reader‑specific hardening
        // -----------------------------------------------------------------
        XMLReader xmlReader = null;
        try {
            SAXParser parser = sfactory.newSAXParser();
            xmlReader = parser.getXMLReader();

            // Disallow DOCTYPE declarations – this is the most effective XXE mitigation.
            try {
                xmlReader.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            } catch (Exception e) {
                LOG.warn("XMLReader does not support disallow-doctype-decl: {}", e.getMessage());
            }
        } catch (Exception ex) {
            LOG.warn("Cannot create SAXParser XMLReader, falling back to default XMLReader: {}", ex.getMessage());
        }

