 * principal appropriately) can perform a self‑update, eliminating the impersonation
 * risk.
 */
public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private final ScimUserProvisioning scimUserProvisioning;

    public ScimUserSelfUpdateAllowed(ScimUserProvisioning scimUserProvisioning) {
        this.scimUserProvisioning = scimUserProvisioning;
    }

    /**
     * Determines whether the incoming HTTP request is allowed to update the user
     * identified by the URL path variable.
     *
     * @param request the HTTP request containing the JSON payload and authentication
     * @return {@code true} if the request is authorized and the payload does not attempt
     *         to modify immutable fields; {@code false} otherwise.
     * @throws IOException if the request body cannot be read.
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // --------------------------------------------------------------------
        // 1. Verify that the request is made by an authenticated principal.
        // --------------------------------------------------------------------
        Principal principal = request.getUserPrincipal();
        if (principal == null) {
            // No authenticated user – deny the operation.
            return false;
        }

        // --------------------------------------------------------------------
        // 2. Extract the target user ID from the request URL.
        // --------------------------------------------------------------------
        String targetUserId = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request)
        );

        if (targetUserId == null || targetUserId.isEmpty()) {
            // Malformed URL – deny.
            return false;
        }

        // --------------------------------------------------------------------
        // 3. Ensure the authenticated user is the owner of the account being
        //    updated (self‑update).  Administrators that need to update other
        //    users should use a different authorisation path.
        // --------------------------------------------------------------------
        String authenticatedUserId = principal.getName();
        if (!Objects.equals(authenticatedUserId, targetUserId)) {
            // The caller is trying to modify someone else’s account – deny.
            return false;
        }

        // --------------------------------------------------------------------
        // 4. Parse the request body into a ScimUser instance.
        // --------------------------------------------------------------------
        String requestBody = IOUtils.toString(request.getReader());
        if (requestBody == null || requestBody.trim().isEmpty()) {
            // Empty payload – deny.
            return false;
        }

        ScimUser scimUserFromRequest;
        try {
            scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);
        } catch (Exception e) {
            // Invalid JSON – deny.
            return false;
        }

        // --------------------------------------------------------------------
        // 5. Load the persisted user record for comparison.
        // --------------------------------------------------------------------
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(targetUserId, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist we cannot safely allow an update.
            // The original code returned true, but that would permit creation
            // of arbitrary accounts via a self‑update endpoint.
            // Returning false is the safer default.
            return false;
        }

        // --------------------------------------------------------------------
        // 6. Compare immutable fields – any change results in denial.
        // --------------------------------------------------------------------
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // All checks passed – the self‑update is allowed.
        return true;
    }

    // other methods (unchanged)
}
